measurement_driver:
import hashlib,json,os,platform,random,statistics,subprocess,time
from pathlib import Path
root=Path(__file__).resolve().parent
paths={name:root/f'compatibility-{name}' for name in ['baseline','validation']}
report={'started_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'cpu':0,'rounds':9,'iterations':1000,'flags':'goose build source/bench.goose --cc gcc -O2','shared_host':True,'platform':platform.platform(),'cc':subprocess.check_output(['gcc','--version'],text=True).splitlines()[0],'builds':{},'samples':[]}
for name,path in paths.items():
 report['builds'][name]={'sha':subprocess.check_output(['git','-C',str(path),'rev-parse','HEAD'],text=True).strip(),'dirty':subprocess.check_output(['git','-C',str(path),'status','--porcelain'],text=True).strip(),'hashes':{f:hashlib.sha256((path/f).read_bytes()).hexdigest() for f in ['source/bench.goose','source/editor.goose','toml.goose','document.goose','writer.goose','vendor/text.goose','source/.build/default-bench']}}
os.sched_setaffinity(0,{0})
def sample(name):
 out=subprocess.check_output([str(paths[name]/'source/.build/default-bench'),'1000'],text=True,timeout=60)
 rows=[line.split('\t') for line in out.splitlines()]
 assert [r[0] for r in rows]==['put_small','remove_small','put_large','remove_large','checksum']
 assert int(rows[-1][1])==sum(int(r[2])*int(r[4]) for r in rows[:-1])
 return {r[0]:int(r[1])/int(r[2]) for r in rows[:-1]}
for name in paths: sample(name)
for i in range(9):
 order=list(paths) if i%2==0 else list(reversed(paths))
 for name in order:report['samples'].append({'round':i,'build':name,'ns_per_op':sample(name)})
report['median_ns_per_op']={name:{case:statistics.median(row['ns_per_op'][case] for row in report['samples'] if row['build']==name) for case in ['put_small','remove_small','put_large','remove_large']} for name in paths}
report['ratios']={case:report['median_ns_per_op']['validation'][case]/report['median_ns_per_op']['baseline'][case] for case in report['median_ns_per_op']['baseline']}
report['completed_utc']=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())
for name,path in paths.items():
 assert subprocess.check_output(['git','-C',str(path),'status','--porcelain'],text=True).strip()==report['builds'][name]['dirty']
 for f,digest in report['builds'][name]['hashes'].items():assert hashlib.sha256((path/f).read_bytes()).hexdigest()==digest
(root/'compatibility-default-performance.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'medians':report['median_ns_per_op'],'ratios':report['ratios']},indent=2))
